-- 0001_baseline: ProbeHarbor schema for Neon (Postgres 18) + Better Auth.
--
-- Source: production public schema from backups/probeharbor-20261107T130635Z.dump
-- (Supabase, Postgres 17.6), taken with pg_restore --schema-only --no-owner
-- --no-privileges -n public, then changed by db/tools/baseline-from-supabase-dump.py:
--   * Better Auth tables (auth_*) added, generated by better-auth 1.7.18 with
--     generateId "uuid" and the twoFactor, passkey and bearer plugins. The Better
--     Auth config in step 4 must use the same model names.
--   * 28 foreign keys moved from auth.users(id) to public.auth_users(id).
--     User ids stay the same UUIDs, so no other table changes.
--   * The two Supabase signup triggers now fire on public.auth_users.
--   * 33 row rules (CREATE POLICY) removed. They guarded Supabase's
--     public database API, which Neon will not have: only the Worker connects,
--     with the owner role. Row level security stays enabled on every table, so
--     any other role sees no rows. Household access is enforced in app code.
--   * Removed is_household_member, is_household_editor,
--     is_household_manager: they read the Supabase session (auth.uid())
--     and only those rules used them.
--   * count_managed_users / list_managed_users read public.auth_users.
--   * EXECUTE on functions revoked from PUBLIC (only the owner role calls them).
--   * Built-in groups seeded (admin, user, member, pro, portfolio), as the
--     Supabase migrations did; signup fails without the 'user' group.

-- SQL functions below refer to tables created after them.
SET check_function_bodies = false;

-- Better Auth tables
create table public."auth_users" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "twoFactorEnabled" boolean);

create table public."auth_sessions" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" uuid not null references public."auth_users" ("id") on delete cascade);

create table public."auth_accounts" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "accountId" text not null, "providerId" text not null, "userId" uuid not null references public."auth_users" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table public."auth_verifications" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table public."auth_two_factors" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "secret" text not null, "backupCodes" text not null, "userId" uuid not null references public."auth_users" ("id") on delete cascade, "verified" boolean, "failedVerificationCount" integer, "lockedUntil" timestamptz);

create table public."auth_passkeys" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "name" text, "publicKey" text not null, "userId" uuid not null references public."auth_users" ("id") on delete cascade, "credentialID" text not null, "counter" integer not null, "deviceType" text not null, "backedUp" boolean not null, "transports" text, "createdAt" timestamptz, "aaguid" text);

create index "auth_sessions_userId_idx" on public."auth_sessions" ("userId");

create index "auth_accounts_userId_idx" on public."auth_accounts" ("userId");

create index "auth_verifications_identifier_idx" on public."auth_verifications" ("identifier");

create index "auth_two_factors_secret_idx" on public."auth_two_factors" ("secret");

create index "auth_two_factors_userId_idx" on public."auth_two_factors" ("userId");

create index "auth_passkeys_userId_idx" on public."auth_passkeys" ("userId");

create index "auth_passkeys_credentialID_idx" on public."auth_passkeys" ("credentialID");


-- Profile settings that lived in Supabase user_metadata (locale, °C, active
-- household, dashboard preferences, github_id, ...). Same JSON, keyed by user.
CREATE TABLE public.user_profiles (
    user_id uuid PRIMARY KEY REFERENCES public.auth_users(id) ON DELETE CASCADE,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_verifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_two_factors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auth_passkeys ENABLE ROW LEVEL SECURITY;

