--
-- Name: count_managed_users(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_managed_users(caller_id uuid, search_text text DEFAULT NULL::text, group_filter text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  safe_search text;
  safe_group text;
begin
  if not public.is_admin_user(caller_id) then
    raise exception 'Forbidden';
  end if;

  safe_search := nullif(btrim(coalesce(search_text, '')), '');
  safe_group := nullif(btrim(coalesce(group_filter, '')), '');
  if safe_group is not null
     and safe_group not in ('admin', 'portfolio', 'pro', 'member', 'user') then
    safe_group := null;
  end if;

  return (
    select count(*)
    from public.auth_users u
    where (
      safe_search is null
      or u.email ilike '%' || replace(replace(replace(safe_search, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
      or u.id::text ilike '%' || replace(replace(replace(safe_search, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
    )
    and (
      safe_group is null
      or exists (
        select 1
        from public.group_members gm_f
        inner join public.groups g_f on g_f.id = gm_f.group_id
        where gm_f.user_id = u.id
          and g_f.name = safe_group
      )
    )
  );
end;
$$;


--
-- Name: ensure_user_household(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_user_household() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  new_household_id uuid;
begin
  if exists (
    select 1 from public.household_members where user_id = new.id
  ) then
    return new;
  end if;

  insert into public.households (name)
  values (coalesce(split_part(new.email, '@', 1), 'My') || '''s household')
  returning id into new_household_id;

  insert into public.household_members (household_id, user_id, role)
  values (new_household_id, new.id, 'owner');

  return new;
end;
$$;


--
-- Name: get_user_household_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_household_id(target_user_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select household_id
  from public.household_members
  where user_id = target_user_id
  order by case when role = 'owner' then 0 else 1 end, created_at
  limit 1;
$$;


--
-- Name: handle_new_user_group_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user_group_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  user_group_id uuid;
begin
  select id
  into user_group_id
  from public.groups
  where name = 'user'
  limit 1;

  if user_group_id is null then
    raise exception 'Default user group not found';
  end if;

  insert into public.group_members (user_id, group_id, role)
  select new.id, user_group_id, 'member'
  where not exists (
    select 1
    from public.group_members
    where user_id = new.id
      and group_id = user_group_id
  );

  return new;
end;
$$;


--
-- Name: is_admin_user(uuid); Type: FUNCTION; Schema: public; Owner: -
