CREATE FUNCTION public.is_admin_user(caller_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.group_members gm
    inner join public.groups g on g.id = gm.group_id
    where gm.user_id = caller_id
      and g.name = 'admin'
  );
$$;


--
-- Name: latest_sensor_readings(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.latest_sensor_readings(p_sensor_ids uuid[]) RETURNS TABLE(sensor_id uuid, value_num double precision, value_bool boolean, value_text text, recorded_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select s.id, r.value_num, r.value_bool, r.value_text, r.recorded_at
  from unnest(p_sensor_ids) as s(id)
  cross join lateral (
    select sr.value_num, sr.value_bool, sr.value_text, sr.recorded_at
    from public.sensor_readings sr
    where sr.sensor_id = s.id
    order by sr.recorded_at desc
    limit 1
  ) r;
$$;


--
-- Name: list_managed_users(uuid, integer, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_managed_users(caller_id uuid, page_num integer DEFAULT 1, page_size integer DEFAULT 20, search_text text DEFAULT NULL::text, group_filter text DEFAULT NULL::text, sort_by text DEFAULT 'created_at'::text, sort_dir text DEFAULT 'desc'::text) RETURNS TABLE(user_id uuid, email text, created_at timestamp with time zone, groups text[], is_admin boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  safe_page integer;
  safe_page_size integer;
  safe_search text;
  safe_group text;
  safe_sort text;
  safe_dir text;
begin
  if not public.is_admin_user(caller_id) then
    raise exception 'Forbidden';
  end if;

  safe_page := greatest(coalesce(page_num, 1), 1);
  safe_page_size := least(greatest(coalesce(page_size, 20), 1), 100);

  safe_search := nullif(btrim(coalesce(search_text, '')), '');
  safe_group := nullif(btrim(coalesce(group_filter, '')), '');
  if safe_group is not null
     and safe_group not in ('admin', 'portfolio', 'pro', 'member', 'user') then
    safe_group := null;
  end if;

  safe_sort := case
    when lower(coalesce(sort_by, '')) = 'email' then 'email'
    else 'created_at'
  end;
  safe_dir := case
    when lower(coalesce(sort_dir, '')) = 'asc' then 'asc'
    else 'desc'
  end;

  return query
  select
    u.id,
    u.email::text,
    u."createdAt",
    coalesce(
      array_agg(distinct g.name order by g.name) filter (where g.name is not null),
      '{}'::text[]
    ),
    exists (
      select 1
      from public.group_members gm_admin
      inner join public.groups g_admin on g_admin.id = gm_admin.group_id
      where gm_admin.user_id = u.id
        and g_admin.name = 'admin'
    )
  from public.auth_users u
  left join public.group_members gm on gm.user_id = u.id
  left join public.groups g on g.id = gm.group_id
  where (
    safe_search is null
    or u.email ilike '%' || replace(replace(replace(safe_search, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
    or u.id::text ilike '%' || replace(replace(replace(safe_search, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
  )
  and (
    safe_group is null
    or exists (
      select 1
      from public.group_members gm_f
      inner join public.groups g_f on g_f.id = gm_f.group_id
      where gm_f.user_id = u.id
        and g_f.name = safe_group
    )
  )
  group by u.id, u.email, u."createdAt"
  order by
    case when safe_sort = 'email' and safe_dir = 'asc' then lower(u.email) end asc nulls last,
    case when safe_sort = 'email' and safe_dir = 'desc' then lower(u.email) end desc nulls last,
    case when safe_sort = 'created_at' and safe_dir = 'asc' then u."createdAt" end asc nulls last,
    case when safe_sort = 'created_at' and safe_dir = 'desc' then u."createdAt" end desc nulls last,
    u."createdAt" desc
  offset (safe_page - 1) * safe_page_size
  limit safe_page_size;
end;
$$;


--
-- Name: replace_device_sensor(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_device_sensor(p_household_id uuid, p_old_sensor_id uuid, p_new_sensor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old public.device_sensors%rowtype;
  v_new public.device_sensors%rowtype;
  v_delta double precision;
  v_readings integer;
  v_rollups integer;
begin
  if p_old_sensor_id = p_new_sensor_id then
    raise exception 'same_sensor';
  end if;

  select s.* into v_old
  from public.device_sensors s
  join public.devices d on d.id = s.device_id
  where s.id = p_old_sensor_id and d.household_id = p_household_id
  for update of s;

  select s.* into v_new
  from public.device_sensors s
  join public.devices d on d.id = s.device_id
  where s.id = p_new_sensor_id and d.household_id = p_household_id
  for update of s;

  if v_old.id is null or v_new.id is null then
    raise exception 'sensor_not_found';
  end if;
  if v_old.kind <> v_new.kind then
    raise exception 'kind_mismatch';
  end if;

  v_delta := coalesce(v_old.offset_num, 0) - coalesce(v_new.offset_num, 0);

  update public.sensor_readings
  set sensor_id = v_new.id,
      household_id = p_household_id,
      value_num = case when value_num is null then null else value_num + v_delta end
  where sensor_id = v_old.id;
  get diagnostics v_readings = row_count;

  insert into public.sensor_reading_rollups as r
    (sensor_id, household_id, bucket_start, avg_num, min_num, max_num, sample_count)
  select v_new.id, p_household_id, bucket_start, avg_num + v_delta, min_num + v_delta, max_num + v_delta, sample_count
  from public.sensor_reading_rollups
  where sensor_id = v_old.id
  on conflict (sensor_id, bucket_start) do update set
    avg_num = case
      when r.sample_count + excluded.sample_count = 0 then coalesce(r.avg_num, excluded.avg_num)
      else (coalesce(r.avg_num, 0) * r.sample_count + coalesce(excluded.avg_num, 0) * excluded.sample_count)
        / (r.sample_count + excluded.sample_count)
    end,
    min_num = least(r.min_num, excluded.min_num),
    max_num = greatest(r.max_num, excluded.max_num),
    sample_count = r.sample_count + excluded.sample_count;
  get diagnostics v_rollups = row_count;
  delete from public.sensor_reading_rollups where sensor_id = v_old.id;

  update public.door_open_events set sensor_id = v_new.id where sensor_id = v_old.id;

  update public.households
  set indoor_reference_sensor_id = v_new.id
  where indoor_reference_sensor_id = v_old.id;

  -- Per-sensor thresholds and scope live in jsonb keyed by sensor uuid; uuids
  -- are unique, so a text swap can't touch anything else.
  update public.alert_settings
  set threshold_sensor_scope = replace(threshold_sensor_scope::text, v_old.id::text, v_new.id::text)::jsonb
  where threshold_sensor_scope::text like '%' || v_old.id::text || '%';

  delete from public.device_sensors where id = v_old.id;

  update public.device_sensors
  set label = v_old.label,
      sort_order = v_old.sort_order,
      visible = v_old.visible
  where id = v_new.id;

  return jsonb_build_object('moved_readings', v_readings, 'moved_rollups', v_rollups);
end;
$$;


--
-- Name: roll_up_and_prune_readings(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roll_up_and_prune_readings(p_cutoff timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rolled_up integer;
  v_deleted integer;
begin
  if p_cutoff is null or p_cutoff > now() - interval '1 day' then
    raise exception 'cutoff_too_recent';
  end if;

  insert into public.sensor_reading_rollups as r
    (sensor_id, household_id, bucket_start, avg_num, min_num, max_num, sample_count)
  select
    sensor_id,
    -- All of a sensor's readings share one household; take any.
    (array_agg(household_id))[1],
    date_trunc('hour', recorded_at at time zone 'UTC') at time zone 'UTC',
    avg(value_num),
    min(value_num),
    max(value_num),
    count(*)::integer
  from public.sensor_readings
  where recorded_at < p_cutoff
    and value_num is not null
  group by sensor_id, date_trunc('hour', recorded_at at time zone 'UTC')
  on conflict (sensor_id, bucket_start) do update set
    avg_num = case
      when r.sample_count + excluded.sample_count = 0 then coalesce(r.avg_num, excluded.avg_num)
      else (coalesce(r.avg_num, 0) * r.sample_count + coalesce(excluded.avg_num, 0) * excluded.sample_count)
        / (r.sample_count + excluded.sample_count)
    end,
    min_num = least(r.min_num, excluded.min_num),
    max_num = greatest(r.max_num, excluded.max_num),
    sample_count = r.sample_count + excluded.sample_count;
  get diagnostics v_rolled_up = row_count;

  delete from public.sensor_readings where recorded_at < p_cutoff;
  get diagnostics v_deleted = row_count;

  return jsonb_build_object('rolled_up', v_rolled_up, 'deleted', v_deleted);
end;
$$;


--
-- Name: rollup_bucket_averages(uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollup_bucket_averages(p_household_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_bucket_seconds integer) RETURNS TABLE(sensor_id uuid, key text, label text, kind text, offset_num double precision, device_name text, bucket_start timestamp with time zone, avg_num double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.sensor_id,
         s.key,
         s.label,
         s.kind,
         s.offset_num::double precision,
         d.name,
         date_bin(make_interval(secs => greatest(p_bucket_seconds, 3600)), r.bucket_start, timestamptz 'epoch') as bucket_start,
         sum(r.avg_num * greatest(r.sample_count, 1)) / sum(greatest(r.sample_count, 1)) as avg_num
  from public.sensor_reading_rollups r
  join public.device_sensors s on s.id = r.sensor_id
  join public.devices d on d.id = s.device_id
  where r.household_id = p_household_id
    and r.bucket_start >= p_from
    and r.bucket_start <= p_to
    and r.avg_num is not null
    and s.kind in ('temperature', 'humidity')
  group by r.sensor_id, s.key, s.label, s.kind, s.offset_num, d.name, 7
  order by 7, 1;
$$;


--
-- Name: sensor_bucket_averages(uuid, uuid[], timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sensor_bucket_averages(p_household_id uuid, p_sensor_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone, p_bucket_seconds integer) RETURNS TABLE(sensor_id uuid, bucket_start timestamp with time zone, avg_num double precision, min_num double precision, max_num double precision, sample_count integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.sensor_id,
         date_bin(make_interval(secs => greatest(p_bucket_seconds, 60)), r.recorded_at, timestamptz 'epoch') as bucket_start,
         avg(r.value_num),
         min(r.value_num),
         max(r.value_num),
         count(*)::integer
  from public.sensor_readings r
  where r.household_id = p_household_id
    and r.sensor_id = any (p_sensor_ids)
    and r.recorded_at >= p_from
    and r.recorded_at <= p_to
    and r.value_num is not null
    -- Bounded work per call.
    and coalesce(cardinality(p_sensor_ids), 0) <= 50
  group by 1, 2
  order by 2, 1;
$$;


--
-- Name: sensor_bucket_samples(uuid, uuid[], uuid[], timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sensor_bucket_samples(p_household_id uuid, p_sensor_ids uuid[], p_extreme_sensor_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone, p_bucket_seconds integer) RETURNS TABLE(sensor_id uuid, recorded_at timestamp with time zone, value_num double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select y.sensor_id, y.recorded_at, y.value_num
  from (
    select x.*,
           row_number() over (partition by x.sensor_id, x.bucket order by x.recorded_at, x.id) as rn_first,
           row_number() over (partition by x.sensor_id, x.bucket order by x.value_num, x.recorded_at, x.id) as rn_min,
           row_number() over (partition by x.sensor_id, x.bucket order by x.value_num desc, x.recorded_at, x.id) as rn_max
    from (
      select r.id, r.sensor_id, r.recorded_at, r.value_num,
             date_bin(make_interval(secs => greatest(p_bucket_seconds, 60)), r.recorded_at, timestamptz 'epoch') as bucket
      from public.sensor_readings r
      where r.household_id = p_household_id
        and r.sensor_id = any (p_sensor_ids)
        and r.recorded_at >= p_from
        and r.recorded_at <= p_to
        and r.value_num is not null
        -- Bounded work per call.
        and coalesce(cardinality(p_sensor_ids), 0) <= 50
    ) x
  ) y
  where y.rn_first = 1
     or ((y.rn_min = 1 or y.rn_max = 1) and y.sensor_id = any (coalesce(p_extreme_sensor_ids, '{}')))
  order by y.recorded_at, y.sensor_id;
$$;


--
-- Name: sensor_values_before(uuid, uuid[], timestamp with time zone[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sensor_values_before(p_household_id uuid, p_sensor_ids uuid[], p_times timestamp with time zone[], p_max_age_seconds integer DEFAULT 1800) RETURNS TABLE(sensor_id uuid, at_time timestamp with time zone, value_num double precision, recorded_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select s.sensor_id, t.at_time, r.value_num, r.recorded_at
  from unnest(p_sensor_ids) as s(sensor_id)
  cross join unnest(p_times) as t(at_time)
  join lateral (
    select sr.value_num, sr.recorded_at
    from public.sensor_readings sr
    where sr.sensor_id = s.sensor_id
      and sr.household_id = p_household_id
      and sr.value_num is not null
      and sr.recorded_at <= t.at_time
      and sr.recorded_at >= t.at_time - make_interval(secs => greatest(p_max_age_seconds, 0))
    order by sr.recorded_at desc
    limit 1
  ) r on true
  -- Bounded work per call: callers batch within these limits.
  where coalesce(cardinality(p_sensor_ids), 0) <= 50
    and coalesce(cardinality(p_times), 0) <= 2000;
$$;


--
-- Name: set_user_admin_membership(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_admin_membership(caller_id uuid, target_user_id uuid, make_admin boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  admin_group_id uuid;
begin
  if not public.is_admin_user(caller_id) then
    raise exception 'Forbidden';
  end if;

  if not make_admin and caller_id = target_user_id then
    raise exception 'Cannot remove your own admin access';
  end if;

  select id
  into admin_group_id
  from public.groups
  where name = 'admin'
  limit 1;

  if admin_group_id is null then
    raise exception 'Admin group not found';
  end if;

  if make_admin then
    insert into public.group_members (user_id, group_id, role)
    select target_user_id, admin_group_id, 'admin'
    where not exists (
      select 1
      from public.group_members
      where user_id = target_user_id
        and group_id = admin_group_id
    );
  else
    delete from public.group_members
    where user_id = target_user_id
      and group_id = admin_group_id;
  end if;
end;
$$;


--
-- Name: sync_member_group_membership(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_group_membership(target_user_id uuid, is_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.sync_plan_group_membership(target_user_id, 'member', is_active);
end;
$$;


--
-- Name: sync_plan_group_membership(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_plan_group_membership(target_user_id uuid, plan_tier text, is_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  member_group_id uuid;
  pro_group_id uuid;
  portfolio_group_id uuid;
begin
  select id into member_group_id from public.groups where name = 'member' limit 1;
  select id into pro_group_id from public.groups where name = 'pro' limit 1;
  select id into portfolio_group_id from public.groups where name = 'portfolio' limit 1;

  if member_group_id is null or pro_group_id is null or portfolio_group_id is null then
    raise exception 'member/pro/portfolio groups not found';
  end if;

  delete from public.group_members
  where user_id = target_user_id
    and group_id in (member_group_id, pro_group_id, portfolio_group_id);

  if is_active then
    if plan_tier = 'portfolio' then
      insert into public.group_members (user_id, group_id, role)
      values (target_user_id, portfolio_group_id, 'member');
      insert into public.group_members (user_id, group_id, role)
      values (target_user_id, pro_group_id, 'member');
      insert into public.group_members (user_id, group_id, role)
      values (target_user_id, member_group_id, 'member');
    elsif plan_tier = 'pro' then
      insert into public.group_members (user_id, group_id, role)
      values (target_user_id, pro_group_id, 'member');
      insert into public.group_members (user_id, group_id, role)
      values (target_user_id, member_group_id, 'member');
    else
      insert into public.group_members (user_id, group_id, role)
      values (target_user_id, member_group_id, 'member');
    end if;
  end if;
end;
$$;


--
-- Name: temperature_reading_counts(uuid, timestamp with time zone, timestamp with time zone, double precision, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.temperature_reading_counts(p_household_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_threshold_f double precision, p_sensor_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(total_count bigint, below_count bigint, from_rollups boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with temp_sensors as (
    select s.id, s.offset_num
    from public.device_sensors s
    join public.devices d on d.id = s.device_id
    where d.household_id = p_household_id
      and s.kind = 'temperature'
      and (p_sensor_ids is null or s.id = any (p_sensor_ids))
  ),
  raw as (
    select count(*) as total,
           count(*) filter (where r.value_num + ts.offset_num <= p_threshold_f) as below
    from public.sensor_readings r
    join temp_sensors ts on ts.id = r.sensor_id
    where r.household_id = p_household_id
      and r.recorded_at >= p_from
      and r.recorded_at <= p_to
      and r.value_num is not null
  ),
  rolled as (
    select coalesce(sum(x.sample_count), 0) as total,
           coalesce(sum(x.sample_count) filter (where x.max_num + ts.offset_num <= p_threshold_f), 0) as below,
           count(*) as hours
    from public.sensor_reading_rollups x
    join temp_sensors ts on ts.id = x.sensor_id
    where x.household_id = p_household_id
      and x.bucket_start >= p_from
      and x.bucket_start <= p_to
  )
  select (raw.total + rolled.total)::bigint,
         (raw.below + rolled.below)::bigint,
         rolled.hours > 0
  from raw, rolled;
$$;


