    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pucks_bay_id_format CHECK (((bay_id IS NULL) OR (bay_id ~ '^[A-Za-z0-9_.:-]{1,32}$'::text))),
    CONSTRAINT pucks_device_id_hex CHECK ((device_id ~ '^[0-9a-f]{32}$'::text)),
